def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_need_count = 0
    rich_aggressive = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                opp_need_count += 1
            if opp.get('budget', 0) >= 300:
                rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    slots = max(1, int(supply / WATER_REQ))
    competitors = 1 + len(alive_opponents)
    scarcity = competitors - slots

    urgent = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1
    tight_supply = supply <= 18
    very_tight = supply <= 15
    late_game = day >= 8

    base = 22.0

    if urgent:
        bid = max(95.0, highest_prev + 2.0, avg_prev + 6.0)
        if very_tight:
            bid += 12.0
        elif tight_supply:
            bid += 6.0
    elif pressured:
        bid = max(58.0, avg_prev * 0.72, highest_prev * 0.62)
        if tight_supply:
            bid += 8.0
        if opp_need_count >= 2:
            bid += 6.0
    else:
        if highest_prev >= 140:
            bid = 19.0
        elif highest_prev >= 90:
            bid = 27.0
        else:
            bid = max(base, avg_prev * 0.38)
        if scarcity >= 3:
            bid += 10.0
        elif scarcity >= 2:
            bid += 5.0
        if rich_aggressive >= 2 and not late_game:
            bid -= 4.0

    if late_game and hp <= 5:
        bid = max(bid, highest_prev * 0.7, 62.0)
    if late_game and urgent:
        bid = max(bid, 110.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 70.0 * (10 - day) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)
    if urgent:
        max_affordable = budget

    bid = min(bid, max_affordable if max_affordable > 0 else budget)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids to infer aggressiveness/pressure
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: if supply barely covers one requirement, expect bidding wars
    # supply is between 15 and 25; with WATER_REQ=9, 15~1 unit, 18~2 units, 25~2 units.
    if supply < (WATER_REQ * 2):
        supply_tight = True
    else:
        supply_tight = False

    # Base bid: aim to be competitive but not top out at extreme bids.
    # Scale with my HP and no-water streak.
    hp_factor = 1.0
    if my_hp <= 1:
        hp_factor = 1.35
    elif my_hp == 2:
        hp_factor = 1.2
    elif my_hp == 3:
        hp_factor = 1.1

    streak_factor = 1.0
    if my_no_water_days >= 2:
        streak_factor = 1.25
    elif my_no_water_days == 1:
        streak_factor = 1.1

    # Opponent aggressiveness: if their highest bid is very high relative to salary, avoid mirroring fully.
    aggressiveness = 0.0
    if highest_prev_bid > 0.0:
        aggressiveness = min(1.0, highest_prev_bid / (DAILY_SALARY * 1.6))

    # Choose target bid level.
    # If supply tight, increase more; if not, keep moderate.
    if supply_tight:
        base = DAILY_SALARY * (0.62 + 0.25 * aggressiveness)
    else:
        base = DAILY_SALARY * (0.48 + 0.18 * aggressiveness)

    # If yesterday average was already high, slightly raise to avoid being outbid.
    if avg_prev_bid > DAILY_SALARY * 1.2:
        base *= 1.08

    bid = base * hp_factor * streak_factor

    # If my HP is critical, push closer to salary cap.
    if my_hp <= 1:
        bid = max(bid, DAILY_SALARY * 0.85)

    # Budget safety and non-negativity
    bid = max(0.0, min(my_budget, bid))

    # If budget is too low, still bid what we can.
    return float(bid)
